-- «نشاطك كما نفهمه» لموقع الإنجاز السريع، من كلام محمود (15 نوفمبر):
-- «احنا بنقدم خدمة استخراج تصاريح الزواج · مش مكتب زواج ولا خطابه · ولا بننشا عقد زواج · ولا يهمنا اللي بيسال عن استعلام المعامله · ولا اللي عايز يقدم بنفسه».
-- يتطبق بعد 0022، ومحمود يقدر يعدّله من صفحة «الكلمات المفتاحية».
insert into site_brief (client_id, offer, exclude)
select id,
  array['تصريح زواج', 'تصاريح زواج', 'موافقة زواج', 'استخراج تصريح', 'معقب', 'مكتب تصاريح'],
  '[{"word":"خطابة","why":"لسنا خطّابة"},{"word":"مكتب زواج","why":"لسنا مكتب زواج"},{"word":"مواقع زواج","why":"لسنا وسيط زواج"},{"word":"منصة زواج","why":"لسنا وسيط زواج"},{"word":"جمعية","why":"لسنا وسيط زواج"},{"word":"تعارف","why":"لسنا وسيط زواج"},{"word":"عقد زواج","why":"لا ننشئ عقود الزواج"},{"word":"مأذون","why":"لا ننشئ عقود الزواج"},{"word":"استعلام","why":"لا نستعلم عن المعاملات"},{"word":"بنفسي","why":"يريد التقديم بنفسه"},{"word":"طريقة","why":"يريد التقديم بنفسه"},{"word":"خطوات","why":"يريد التقديم بنفسه"},{"word":"كيفية","why":"يريد التقديم بنفسه"},{"word":"نموذج","why":"يريد التقديم بنفسه"},{"word":"ابشر","why":"يريد التقديم بنفسه"},{"word":"تجنيس","why":"لا نقدم خدمات التجنيس"}]'::jsonb
from clients where name like '%الانجاز%' or name like '%الإنجاز%'
on conflict (client_id) do update set offer = excluded.offer, exclude = excluded.exclude, updated_at = now();
